  score: ['સ્કોર', 'स्कोर', 'Score'], reset: ['ફરીથી', 'फिर से', 'Reset'], see_fig: ['👇 આકૃતિ જોઈને જવાબ આપો', '👇 चित्र देखकर जवाब दो', '👇 Look at the figure to answer'],
