  ar_ci: ['કૂલન્ટ અંદર', 'कूलेंट अंदर', 'Coolant in'], ar_co: ['કૂલન્ટ બહાર', 'कूलेंट बाहर', 'Coolant out'],
  act_h: ['⚙️ એક્ચ્યુએટર કેવી રીતે કામ કરે? (લાઇવ)', '⚙️ एक्चुएटर कैसे काम करता है? (लाइव)', '⚙️ How the actuator works (live)'],
  act_p: [
    '<li>ડબ્બીની અંદર રબરનું <b>ડાયાફ્રામ</b> અને <b>સ્પ્રિંગ</b> છે. સ્પ્રિંગ વેસ્ટગેટને <b>બંધ</b> દબાવી રાખે.</li><li>કમ્પ્રેસરનું <b>બૂસ્ટ પ્રેશર</b> પાતળી હોઝથી ડાયાફ્રામની એક બાજુ આવે.</li><li>બૂસ્ટ સ્પ્રિંગના જોર (≈ 1.1 bar) કરતાં વધે → ડાયાફ્રામ ખસે → <b>રોડ</b> ધકેલાય → વેસ્ટગેટ <b>ખૂલે</b>.</li><li>થોડો ગેસ ટર્બાઇનને બાયપાસ કરે → ટર્બો ધીમો પડે → બૂસ્ટ ઘટે → સ્પ્રિંગ ફરી બંધ કરે. આમ બૂસ્ટ <b>આપોઆપ કાબૂમાં</b> રહે.</li>',
    '<li>डिब्बी के अंदर रबर का <b>डायाफ्राम</b> और <b>स्प्रिंग</b> है। स्प्रिंग वेस्टगेट को <b>बंद</b> दबाए रखती है।</li><li>कंप्रेसर का <b>बूस्ट प्रेशर</b> पतली होज़ से डायाफ्राम की एक तरफ़ आता है।</li><li>बूस्ट स्प्रिंग के ज़ोर (≈ 1.1 bar) से बढ़े → डायाफ्राम खिसकता है → <b>रॉड</b> धकेली जाती है → वेस्टगेट <b>खुलता</b> है।</li><li>थोड़ी गैस टर्बाइन को बायपास करती है → टर्बो धीमा होता है → बूस्ट घटता है → स्प्रिंग फिर बंद करती है। इस तरह बूस्ट <b>अपने आप काबू में</b> रहता है।</li>',
    '<li>Inside the can are a rubber <b>diaphragm</b> and a <b>spring</b>. The spring holds the wastegate <b>shut</b>.</li><li><b>Boost pressure</b> from the compressor reaches one side of the diaphragm through a thin hose.</li><li>Boost beats the spring (≈ 1.1 bar) → the diaphragm moves → the <b>rod</b> is pushed → the wastegate <b>opens</b>.</li><li>Some gas bypasses the turbine → the turbo slows → boost falls → the spring closes it again. So boost <b>controls itself</b>.</li>'],
  act_full: ['🦶 ફુલ એક્સિલરેટર', '🦶 फुल एक्सीलरेटर', '🦶 Full accelerator'], act_rel: ['છોડી દો', 'छोड़ दो', 'Release'], act_3d: ['🔍 3D માં અંદરથી જુઓ', '🔍 3D में अंदर से देखो', '🔍 See inside in 3D'],
  act_c: ['સ્પ્રિંગ જીતે છે → વેસ્ટગેટ બંધ', 'स्प्रिंग जीतती है → वेस्टगेट बंद', 'Spring wins → wastegate closed'], act_o: ['બૂસ્ટ જીતે છે → વેસ્ટગેટ ખુલ્લો', 'बूस्ट जीतता है → वेस्टगेट खुला', 'Boost wins → wastegate open'],
  act_w: [['બૂસ્ટ', 'ડાયાફ્રામ', 'સ્પ્રિંગ', 'રોડ', 'વેસ્ટગેટ', 'એક્ઝોસ્ટ ગેસ', 'બાયપાસ'], ['बूस्ट', 'डायाफ्राम', 'स्प्रिंग', 'रॉड', 'वेस्टगेट', 'एग्जॉस्ट गैस', 'बायपास'], ['Boost', 'Diaphragm', 'Spring', 'Rod', 'Wastegate', 'Exhaust gas', 'Bypass']],
  spec_note: ['માપ અને સ્પેસિફિકેશન ટ્રેનિંગ માટેના ટિપિકલ આંકડા છે – હંમેશા કંપનીના મેન્યુઅલ પ્રમાણે કામ કરો.', 'माप और स्पेसिफिकेशन ट्रेनिंग के टिपिकल आँकड़े हैं – हमेशा कंपनी के मैनुअल के अनुसार काम करो।', 'Values and specifications are typical training figures – always follow the manufacturer’s manual.']
